use maho_rpc::{session_worker_client::{WorkerControls,WorkerControl},session_worker_protocol::*};
#[test]fn typed_control_ack_releases_latest_display_envelope(){let mut controls=WorkerControls::default();let display=|revision|WorkerDisplay{revision,width:80.,rendered:false,capabilities:vec![]};assert_eq!(controls.post_envelope(WorkerControl::Display(display(1.))),Some(HostToSessionWorker::Display{display:display(1.)}));assert!(controls.post_envelope(WorkerControl::Display(display(2.))).is_none());assert!(controls.post_envelope(WorkerControl::Display(display(3.))).is_none());assert_eq!(controls.receive_control_done(WorkerControlKind::Display),Some(HostToSessionWorker::Display{display:display(3.)}));assert!(controls.post_envelope(WorkerControl::CancelUi).is_some());assert!(controls.post_envelope(WorkerControl::CancelUi).is_none());controls.receive_control_done(WorkerControlKind::CancelUi);assert!(controls.post_envelope(WorkerControl::CancelUi).is_some());controls.stop();assert!(controls.post_envelope(WorkerControl::Display(display(4.))).is_none());}
